create table veranolink.vl_companies (
    vl_id_company number generated by default as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache 20 noorder
    nocycle nokeep noscale not null enable,
    name          varchar2(100 byte),
    vl_id_country number,
    created_date  date,
    short_name    varchar2(30 byte)
);

alter table veranolink.vl_companies add primary key ( vl_id_company )
    using index enable;


